-- ============================================================================
-- COMP214 - ONLINE BOOKSTORE - MASTER SEED / DATA INITIALIZATION
-- Source: nine user-provided CSV / SQL files; audit/log seed inserts intentionally omitted.
-- Prepared: 2026-11-17; all generated dates 2026-01-01 through 2026-11-17.
-- Designed for the EXISTING 12 tables in COMP214_Create_Tables_v4.sql.
-- AUTHOR_ORDER is assigned deterministically in each book's source contributor order.
-- RETURN_REASON is mapped to the six DDD-controlled values.
-- See COMP214_Return_Reason_Mapping.csv for the exact transformations.
-- Does NOT create tables, packages, triggers, embeddings, or vector indexes.
-- Source data is synthetic/educational or transformed Kaggle data.
-- PRICE_AUDIT and EMBEDDING_LOG remain empty after the seed load.
-- Run on EMPTY seed-target tables only. No automatic deletion of user data.
-- Script mode: Oracle SQL Developer F5 / SQLcl / SQL*Plus.
-- IMPORTANT: Do NOT deploy stock/restock triggers before loading this seed.
-- ORIGINAL ISBN WARNING: book ISBNs may have been rounded in an earlier CSV.
-- They are preserved as provided and MUST NOT be treated as verified ISBNs.
-- Author COUNTRY: Not provided (unknown; not invented).
-- Author BIO: generated catalogue-credit summaries, not biographies.
-- CATEGORIES.DESCRIPTION: editorial definitions generated for the project.
-- REVIEW_EMBEDDING / DESCRIPTION_EMBEDDING intentionally NULL until computed.
-- Empty refund amounts for Request/Reject preserved as semantically NULL.
-- ============================================================================
SET DEFINE OFF
SET SERVEROUTPUT ON;
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;

-- Fail safely if any target table already has records (FK-safe, no deleting).
DECLARE
  v_count NUMBER;
BEGIN
  FOR t IN (SELECT column_value AS tbl FROM TABLE(SYS.ODCIVARCHAR2LIST('CATEGORIES','ORDER_STATUS','AUTHORS','BOOKS','BOOK_AUTHORS','CUSTOMERS','ORDERS','ORDER_ITEMS','RETURNS','REVIEWS','PRICE_AUDIT','EMBEDDING_LOG'))) LOOP
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || DBMS_ASSERT.SIMPLE_SQL_NAME(t.tbl) INTO v_count;
    IF v_count > 0 THEN RAISE_APPLICATION_ERROR(-20051, 'Seed aborted: ' || t.tbl || ' already has ' || v_count || ' rows.'); END IF;
  END LOOP;
END;
/

-- A. LOOKUP TABLES
-- Original category classification: IDs 1 through 18 (18=Unclassified, no selected books).

-- Original ORDER_STATUS values.

-- B. AUTHORS: source IDs preserved; descriptive author bio derived from linked catalogue titles.

-- C. BOOKS: preserve original explicit BOOK_ID 1..100 for FK relationships.
-- CREATED_AT, UPDATED_AT are simulated catalog system dates within 2026.

-- D. BOOK_AUTHORS junction table: references existing parent rows.

-- E. CUSTOMERS: original identifiers + existing synthetic Canadian addresses;
-- CREATED_AT synthesized before customer purchases.

-- F. ORDERS (50) then ORDER_ITEMS (275), preserved existing prices and totals.
-- SHIPPED_DATE is populated only for SHIPPED/DELIVERED orders; otherwise NULL.

-- G. ORDER_ITEMS: parent order/book refs in place.

-- H. RETURNS: 25 records, linked only to DELIVERED orders.

-- I. REVIEWS: 150 synthetic records; vectors generated separately.

-- J. PRICE_AUDIT and EMBEDDING_LOG are intentionally NOT seeded.
-- These tables start empty and are populated only by actual price changes,
-- embedding generation/refresh operations, and the associated triggers/packages.
-- Do not add fabricated audit events or embedding activity at initialization.

COMMIT;

-- L. SEQUENCES: SEQ_*_ID convention. Provision where absent; synchronize to MAX(primary_key)+1.
-- Safe for existing SEQ_BOOK_ID: ALTER SEQUENCE RESTART, not DROP/CREATE.
-- Existing explicit seed identifiers remain unchanged.
-- All new future inserts that omit the PK use DEFAULT ON NULL NEXTVAL.
-- Oracle 23ai / Autonomous AI Database syntax.
DECLARE
  v_exists NUMBER;
  v_start NUMBER;
  TYPE t_names IS TABLE OF VARCHAR2(30) INDEX BY PLS_INTEGER;
  v_tabs t_names;
  v_keys t_names;
  v_seqs t_names;
BEGIN
  v_tabs(1) := 'BOOKS'; v_keys(1) := 'BOOK_ID'; v_seqs(1) := 'SEQ_BOOK_ID';
  v_tabs(2) := 'AUTHORS'; v_keys(2) := 'AUTHOR_ID'; v_seqs(2) := 'SEQ_AUTHOR_ID';
  v_tabs(3) := 'CUSTOMERS'; v_keys(3) := 'CUSTOMER_ID'; v_seqs(3) := 'SEQ_CUSTOMER_ID';
  v_tabs(4) := 'ORDERS'; v_keys(4) := 'ORDER_ID'; v_seqs(4) := 'SEQ_ORDER_ID';
  v_tabs(5) := 'ORDER_ITEMS'; v_keys(5) := 'ORDER_ITEM_ID'; v_seqs(5) := 'SEQ_ORDER_ITEM_ID';
  v_tabs(6) := 'RETURNS'; v_keys(6) := 'RETURN_ID'; v_seqs(6) := 'SEQ_RETURN_ID';
  v_tabs(7) := 'REVIEWS'; v_keys(7) := 'REVIEW_ID'; v_seqs(7) := 'SEQ_REVIEW_ID';
  v_tabs(8) := 'PRICE_AUDIT'; v_keys(8) := 'AUDIT_ID'; v_seqs(8) := 'SEQ_PRICE_AUDIT_ID';
  v_tabs(9) := 'EMBEDDING_LOG'; v_keys(9) := 'LOG_ID'; v_seqs(9) := 'SEQ_EMBEDDING_LOG_ID';
  v_tabs(10) := 'CATEGORIES'; v_keys(10) := 'CATEGORY_ID'; v_seqs(10) := 'SEQ_CATEGORY_ID';
  v_tabs(11) := 'ORDER_STATUS'; v_keys(11) := 'STATUS_ID'; v_seqs(11) := 'SEQ_ORDER_STATUS_ID';
  FOR i IN 1..v_tabs.COUNT LOOP
    SELECT COUNT(*) INTO v_exists FROM USER_SEQUENCES WHERE SEQUENCE_NAME = v_seqs(i);
    IF v_exists = 0 THEN EXECUTE IMMEDIATE 'CREATE SEQUENCE ' || v_seqs(i) || ' START WITH 1 INCREMENT BY 1 NOCYCLE NOCACHE'; END IF;
    EXECUTE IMMEDIATE 'SELECT NVL(MAX(' || v_keys(i) || '),0)+1 FROM ' || v_tabs(i) INTO v_start;
    EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || v_seqs(i) || ' RESTART START WITH ' || TO_CHAR(v_start);
    EXECUTE IMMEDIATE 'ALTER TABLE ' || v_tabs(i) || ' MODIFY ' || v_keys(i) || ' DEFAULT ON NULL ' || v_seqs(i) || '.NEXTVAL';
    DBMS_OUTPUT.PUT_LINE(v_tabs(i) || ': ' || v_seqs(i) || ' next value = ' || v_start);
  END LOOP;
END;
/

-- BOOK_AUTHORS is a junction table with composite PK: no sequence required.
-- If a BEFORE INSERT trigger also assigns a primary key, review it to ensure
-- it does not consume a second sequence value or replace explicit values.

-- L. VALIDATION
SELECT 'CATEGORIES' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM CATEGORIES UNION ALL
SELECT 'ORDER_STATUS', COUNT(*) FROM ORDER_STATUS UNION ALL
SELECT 'AUTHORS', COUNT(*) FROM AUTHORS UNION ALL
SELECT 'BOOKS', COUNT(*) FROM BOOKS UNION ALL
SELECT 'BOOK_AUTHORS', COUNT(*) FROM BOOK_AUTHORS UNION ALL
SELECT 'CUSTOMERS', COUNT(*) FROM CUSTOMERS UNION ALL
SELECT 'ORDERS', COUNT(*) FROM ORDERS UNION ALL
SELECT 'ORDER_ITEMS', COUNT(*) FROM ORDER_ITEMS UNION ALL
SELECT 'RETURNS', COUNT(*) FROM RETURNS UNION ALL
SELECT 'REVIEWS', COUNT(*) FROM REVIEWS UNION ALL
SELECT 'PRICE_AUDIT', COUNT(*) FROM PRICE_AUDIT UNION ALL
SELECT 'EMBEDDING_LOG', COUNT(*) FROM EMBEDDING_LOG ORDER BY TABLE_NAME;

-- No orphan BOOK_AUTHORS refs:
SELECT COUNT(*) AS ORPHAN_BOOK_AUTHORS FROM BOOK_AUTHORS BA
LEFT JOIN BOOKS B ON BA.BOOK_ID=B.BOOK_ID
LEFT JOIN AUTHORS A ON BA.AUTHOR_ID=A.AUTHOR_ID
WHERE B.BOOK_ID IS NULL OR A.AUTHOR_ID IS NULL;
-- Expected: 0

SELECT COUNT(*) AS ORDERS_TOTAL_MISMATCH FROM ORDERS O
JOIN (SELECT ORDER_ID, SUM(QUANTITY*UNIT_PRICE) AS TOTAL FROM ORDER_ITEMS GROUP BY ORDER_ID) I
  ON O.ORDER_ID=I.ORDER_ID WHERE ABS(O.TOTAL_AMOUNT-I.TOTAL) > 0.005;
-- Expected: 0

SELECT COUNT(*) AS INVALID_RETURN_DATE FROM RETURNS R
JOIN ORDER_ITEMS I ON I.ORDER_ITEM_ID=R.ORDER_ITEM_ID
JOIN ORDERS O ON O.ORDER_ID=I.ORDER_ID
WHERE R.RETURN_DATE <= O.ORDER_DATE;
-- Expected: 0

SELECT COUNT(*) AS INVALID_2026_DATE FROM (
 SELECT CREATED_AT AS D FROM BOOKS UNION ALL SELECT UPDATED_AT FROM BOOKS
 UNION ALL SELECT CREATED_AT FROM CUSTOMERS UNION ALL SELECT ORDER_DATE FROM ORDERS
 UNION ALL SELECT RETURN_DATE FROM RETURNS UNION ALL SELECT REVIEW_DATE FROM REVIEWS

) WHERE D < DATE '2026-01-01' OR D >= DATE '2026-11-18';
-- Expected: 0

-- Confirm audit/log tables are empty immediately after a clean seed:
SELECT COUNT(*) AS PRICE_AUDIT_COUNT FROM PRICE_AUDIT; -- Expected: 0
SELECT COUNT(*) AS EMBEDDING_LOG_COUNT FROM EMBEDDING_LOG; -- Expected: 0

-- Optional quick check: newly assigned keys would be > existing max.
SELECT MAX(BOOK_ID) AS MAX_BOOK_ID FROM BOOKS;
SELECT MAX(ORDER_ID) AS MAX_ORDER_ID FROM ORDERS;

-- Validate shipping date consistency (expected: 0).
SELECT COUNT(*) AS INVALID_SHIPPED_DATE FROM ORDERS
WHERE SHIPPED_DATE < ORDER_DATE;

-- Check shipped/delivered orders have a shipping date (expected: 0).
SELECT COUNT(*) AS MISSING_SHIPPED_DATE FROM ORDERS O
JOIN ORDER_STATUS S ON S.STATUS_ID = O.STATUS_ID
WHERE S.STATUS_NAME IN ('SHIPPED', 'DELIVERED')
  AND O.SHIPPED_DATE IS NULL;

-- END OF MASTER SEED.
