INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (1, '9780410000000', 'Adrian Mole: The Wilderness Years', 1, 'Methuen Publishing Company', 1993, 1.46, 50, 'Adrian Mole has at last reached physical maturity, but he can''t help roaming the pages of his diary like an untamed adolescent. Finally given the heave-ho by Pandora, he seeks solace in the arms of Bianca, a qualified hydraulic engineer masquerading as a waitress. Between his dishwashing job and completing his epic novel, ''Lo! The Flat Hills of My Homeland'', Adrian hopes that fame and fortune will not keep him waiting much longer.', DATE '2026-01-04', DATE '2026-01-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (2, '9781430000000', 'Dawn', 1, 'BiblioLife', 2007, 36.3, 45, 'This is a pre-1923 historical reproduction that was curated for quality. Quality assurance was conducted on each of these books in an attempt to remove books with imperfections introduced by the digitization process. Though we have made best efforts - the books may have occasional errors that do not impede the reading experience. We believe this work is culturally important and have elected to bring the book back into print as part of our continuing commitment to the preservation of printed works worldwide.', DATE '2026-01-07', DATE '2026-01-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (3, '9780840000000', 'The Indwelling', 1, 'Tyndale House Publishers', 2001, 3.12, 10, 'Nicolae Carpathia is dead. But who killed the Antichrist? The answer may surprise you. Book seven in the best-selling Left Behind series marks the beginning of the second half of the seven-year Tribulation period. In dramatic fashion, readers are exposed to the horrors of God''s judgment and the hope of salvation. Rayford, Buck, Chloe, and the rest of the Tribulation Force find themselves at the center of heart-stopping action. Number one on the "New York Times" Best Sellers List for four weeks.', DATE '2026-01-10', DATE '2026-01-31');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (4, '9780700000000', 'The Road Home', 1, 'Chatto and Windus', 2007, 0.85, 24, 'Lev is on his way to Britain to seek work, so that he can send money back to eastern Europe to support his mother and little daughter. He struggles with the mysterious rituals of ''Englishness'', and the fashions and fads of the London scene. We see the road Lev travels through his eyes, and we share his dilemmas.', DATE '2026-01-13', DATE '2026-02-10');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (5, '9780190000000', 'Winesburg, Ohio', 1, 'Oxford University Press, USA', 1999, 4.41, 22, 'Winesburg, Ohio depicts the strange, secret lives of the inhabitants of a small town. In "Hands," Wing Biddlebaum tries to hide the tale of his banishment from a Pennsylvania town, a tale represented by his hands. In "Adventure," lonely Alice Hindman impulsively walks naked into the night rain. Threaded through the stories is the viewpoint of George Willard, the young newspaper reporter who, like his creator, stands witness to the dark and despairing dealings of a community of isolated people.', DATE '2026-01-16', DATE '2026-02-20');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (6, '9781880000000', 'Working Parts', 1, 'Seal Press', 1997, 6.27, 50, 'An engaging debut novel about two individuals who challenge themselves and each other through friendship, commitment, reading, and sportLesbian cyclist Lori Taylor is an exceedingly likable, top-notch bike mechanic. She''s a smart woman with an embarrassing secret: she can''t read. Her best friend Mickey, also a bike mechanic, is long on literacy but he often comes up short on love. In Lucy Jane Bledsoe''s first novel, the two friends enter into a pact that leads each of them into dangerous emotional territory. As they negotiate the rough ride of personal growth and strained friendship, the mutual dream that drove them to the pact begins to unravel. Set at breakneck speed, Working Parts dazzles with its vibrant prose, memorable characters, and snappy dialogue. Bledsoe''s increasing number of fans will eagerly welcome this fully realized story.', DATE '2026-01-19', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (7, '9781550000000', 'All My Friends are Superheroes', 2, 'Coach House Press', 2003, 4.64, 48, 'All Tom''s friends really are superheroes.There''s the Ear, the Spooner, the Impossible Man. Tom even married a superhero, the Perfectionist. But at their wedding, the Perfectionist was hypnotized (by ex-boyfriend Hypno, of course) to believe that Tom is invisible. Nothing he does can make her see him. Six months later, she''s sure that Tom has abandoned her.So she''s moving to Vancouver. She''ll use her superpower to make Vancouver perfect and leave all the heartbreak in Toronto. With no idea Tom''s beside her, she boards an airplane in Toronto. Tom has until the wheels touch the ground in Vancouver to convince her he''s visible, or he loses her forever.', DATE '2026-01-22', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (8, '9781860000000', 'Lady Cottington''s Pressed Fairy Book', 2, 'Pavilion', 1994, 7.08, 44, 'This is a reproduction of the diary of Lady Angelica Cottingham, which features pressed garden fairies. Or rather the psychic images of the fairies, who quickly turned it into a game, where they leapt between the closing pages in an effort to outdo each other to produce the most outrageous poses.', DATE '2026-01-25', DATE '2026-03-22');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (9, '9788500000000', 'Nora ez dakizun hori', 2, 'Elkar', 2009, 21.04, 30, 'Bi istorio lotzen dituen eleberria da: alde batetik Martin argazkilaria, munduan zehar argazki misteriotsuak egin ondoren, itzuli eta gauero irrati-programa bera entzuten duen Elias kazetariaren etxean bizi dena; bestetik, Nora, irrati-esataria, bizi izan duen bizitza gogorraren amaiera gertu duen amonaren etxean bizi dena eta ama berarekin haurdun zegoela istripuz hil zitzaiona. Bi istorioak lotzen joango dira kontakizunean zehar, likantropo baten istorioak tarteko.', DATE '2026-01-28', DATE '2026-04-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (10, '9788800000000', 'Selina Penaluna', 2, 'Mondadori', 2008, 5.2, 50, 'Selina Penaluna is a merrymaid or so she believes . . . Ellen and Jack are evacuated from London to Cornwall during the Second World War. Ellen relishes the opportunity to better herself. Jack is different. He finds the attention from his new family stifling and seeks freedom in the arms of Selina, the mysterious local girl he sees at the shore. Selina, Ellen and Jack''s lives are intertwined in a series of events that lead to tragedy.', DATE '2026-01-31', DATE '2026-02-05');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (11, '9781940000000', 'Shadow''s Fall', 2, 'Ace', 2012, 2.54, 26, 'For three years, Miranda Grey-Solomon has kept her role as Vampire Queen of the South separate from her Grammy-winning music career. But now, her dual lives are starting to collide, threatening everything Miranda and David, her Prime, have worked for.The entire Signet Council has descended upon Austin for its ten-year summit, bringing with it Prime James Hart of the Northeast, a sworn enemy come to take his revenge on those who defied him. But Miranda and David receive an unexpected offer of help from David''s sire, an ancient and powerful vampire with knowledge that may be their salvation--or their doom.', DATE '2026-02-03', DATE '2026-02-15');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (12, '9781780000000', 'The Dark Wild', 2, 'Quercus', 2014, 2.82, 39, 'Twelve-year-old Kester thought he had discovered the last wild animals in the land. He thought his adventure was over. He was wrong.Below the sparkling city of Premium, deep underground, a dark wild remains: animals who believe the time is right to rise up against their human enemies.And soon Kester realises: he is the only one who can stop them.Kester Jaynes saved the animals. Can he save the humans too?', DATE '2026-02-06', DATE '2026-02-25');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (13, '9780360000000', 'Babylon''s Ashes', 3, 'Orbit', 2016, 11.34, 40, 'The sixth book in the New York Times bestselling Expanse series. NOW A MAJOR TV SERIES A revolution brewing for generations has begun in fire. It will end in blood.The Free Navy - a violent group of Belters in black-market military ships - has crippled the Earth and begun a campaign of piracy and violence among the outer planets. The colony ships heading for the thousand new worlds on the far side of the alien ring gates are easy prey, and no single navy remains strong enough to protect them.James Holden and his crew know the strengths and weaknesses of this new force better than anyone. Outnumbered and outgunned, the embattled remnants of the old political powers call on the Rocinante for a desperate mission to reach Medina Station at the heart of the gate network. But the new alliances are as flawed as the old, and the struggle for power has only just begun. As the chaos grows, an alien mystery deepens. Pirate fleets, mutiny and betrayal may be the least of the Rocinante''s problems. And in the uncanny spaces past the ring gates, the choices of a few damaged and desperate people may determine the fate of more than just humanity.', DATE '2026-02-09', DATE '2026-03-07');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (14, '9780560000000', 'Doctor Who: Trading Futures', 3, 'BBC Books', 2002, 3.58, 12, '''Welcome to the future.''The early decades of the twenty-first century. All the wars have been won. There are no rogue states. The secret services of the world keep the planet electronically monitored, safe from all threat. There is no one left for United States and the Eurozone to fight. Except each other.A mysterious time traveller offers a better future - he has a time machine, and with it, humanity could reach the next stage of evolution, they could share its secrets and become the new Lords of Time......either that, or someone could keep the technology for themselves and use it to fight the ultimate war.A Classic Doctor Who Adventure featuring the Eighth Doctor as played by Paul McGann.', DATE '2026-02-12', DATE '2026-03-17');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (15, '9780740000000', 'Nova', 3, 'Pocket Books', 2006, 7.3, 23, 'Four years after the end of the Brood War, Emperor Arcturus Mengsk has rebuilt much of the Terran Dominion and consolidated a new military force despite an ever-present alien threat. Within this boiling cauldron of strife and subversion, a young woman known only as Nova shows the potential to become Mengsk''s most lethal and promising "Ghost" operative. Utilizing a combination of pure physical aptitude, innate psychic power, and advanced technology, Nova can strike anywhere with the utmost stealth. Like a phantom in the shadows, she exists only as a myth to the enemies of the Terran Dominion. Yet Nova wasn''t born a killer. She was once a privileged child of one of the Old Families of the Terran Confederacy, but her life changed forever when a rebel militia murdered her family. In her grief, Nova unleashed her devastating psychic powers, killing hundreds in a single, terrible moment. Now, on the run through the slums of Tarsonis, she is unable to trust anyone. Pursued by a special agent tasked with hunting down rogue telepaths, Nova must come to terms with both her burgeoning powers and her guilt -- before they consume her and destroy everything in her path....', DATE '2026-02-15', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (16, '9780530000000', 'The Evolution of Claire', 3, 'Random House Books for Young Readers', 2018, 40.08, 12, 'Discover the beginnings of one of Jurassic World ''s most beloved characters--Claire Dearing--in this original action-packed young adult novel. During the events of Jurassic World, Claire Dearing faced the savage fury of dinosaurs unleashed . . . but it wasn''t the first time. In this entirely new coming-of-age story, Claire lands an elite internship working for Simon Masrani and soon discovers his plans to build an all-new theme park--Jurassic World! Along the way, Claire establishes valuable relationships with both her peers and the prehistoric creatures she studies, but when the situation turns dangerous, she begins to see the dinosaurs in a different light. Fans of Jurassic World will delight in filling in the gaps of Claire''s past, all while gaining insights into the experiences that transformed her into the strong woman we know today.Jurassic World: Fallen Kingdom is being directed by J. A. Bayona (The Impossible, A Monster Calls), with Steven Spielberg and Colin Trevorrow serving as executive producers and Frank Marshall and Pat Crowley as producers.', DATE '2026-02-18', DATE '2026-04-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (17, '9780890000000', 'The Faded Sun Trilogy', 3, 'Daw Books', 2000, 4.49, 39, 'They were the mri - tall, secretive, bound by honor and the rigid dictates of their society. For aeons this golden-skinned, golden-eyed race had provided the universe mercenary soldiers of almost unimaginable ability. But now the mri have faced an enemy unlike any other - an enemy whose only way of war is widespread destruction. These "humans" are mass fighters, creatures of the herd, and the mri have been slaughtered like animals.Now, in the aftermath of war, the mri face extinction. It will be up to three individuals to save whatever remains of this devastated race: a warrior - one of the last survivors of his kind; a priestess of this honorable people; and a lone human - a man sworn to aid the enemy of his own kind. Can they retrace the galaxy-wide path of this nomadic race back through millennia to reclaim the ancient world which first gave them life? "This is a powerful story...inspiring in its determination and feeling of strange loyalties and stranger courage. It sticks in the mind long after the last page is finished."-- Analog', DATE '2026-02-21', DATE '2026-04-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (18, '9780520000000', 'The Rowan', 3, 'Random House Value Publishing', 1992, 6.6, 48, 'Told in the timeless style of Anne McCaffrey, The Rowan is the first installment in a wonderful trilogy. This is sci-fi at its best: a contemporary love story as well as an engrossing view of our world in the future.The kinetically gifted, trained in mind/machine gestalt, are the most valued citizens of the Nine Star League. Using mental powers alone, these few Prime Talents transport ships, cargo and people between Earth''s Moon, Mars'' Demos and Jupiter''s Callisto.An orphaned young girl, simply called The Rowan, is discovered to have superior telepathic potential and is trained to become Prime Talent on Callisto. After years of self-sacrificing dedication to her position, The Rowan intercepts an urgent mental call from Jeff Raven, a young Prime Talent on distant Deneb. She convinces the other Primes to merge their powers with hers to help fight off an attack by invading aliens. Her growing relationship with Jeff gives her the courage to break her status-imposed isolation, and choose the more rewarding world of love and family.', DATE '2026-02-24', DATE '2026-04-26');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (19, '9781460000000', 'Blue Labyrinth', 4, 'Grand Central Publishing', 2014, 1.92, 21, 'Special Agent Pendergast-one of the most original, compelling characters in all of contemporary fiction-returns in Preston and Child''s new exhilarating novel Blue Labyrinth.A long-buried family secret has come back to haunt Special Agent Aloysius Pendergast...It begins with murder. One of Pendergast''s most implacable, most feared enemies is found on his doorstep, dead. Pendergast has no idea who is responsible for the killing, or why the body was brought to his home. The mystery has all the hallmarks of the perfect crime, save for an enigmatic clue: a piece of turquoise lodged in the stomach of the deceased.The gem leads Pendergast to an abandoned mine on the shore of California''s Salton Sea, which in turn propels him on a journey of discovery deep into his own family''s sinister past. But Pendergast learns there is more at work than a ghastly episode of family history: he is being stalked by a subtle killer bent on vengeance over an ancient transgression. And he soon becomes caught in a wickedly clever plot, which leaves him stricken in mind and body, and propels him toward a reckoning beyond anything he could ever have imagined...', DATE '2026-02-27', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (20, '9781340000000', 'Get Out of Town', 4, 'Scholastic Inc', 2019, 2.84, 26, 'When Archie, Betty, Veronica and Jughead take a road trip, they discover that their small-town problems seem to follow them wherever they go.Archie''s on trial for murder, and the evidence is stacked against him. Betty, Veronica, and Jughead all know that Archie is being framed by Hiram Lodge, but how can they prove it?The gang comes up with a last-ditch plan to prove Archie''s innocence: They have to go back to the scene of the crime. They have to go back to Shadow Lake.Threats are around every corner deep in the woods at the Lodge family cabin. Will the teens find the evidence they need to clear Archie''s name? And more importantly, will they make it back to Riverdale alive?', DATE '2026-03-02', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (21, '9781930000000', 'Hell''s Half Acre', 4, 'MacAdam/Cage Publishing', 2004, 18.4, 10, 'Kidnapping, snuff films, amputee geeks and a requiem of lost love.Cast adrift after the blood symphony of Penny Dreadful, Phineas Poe is looking for answers in the form of a woman. He tracks Jude to San Francisco, where he finds her involved with John Ransom Miller, a wealthy sociopath with a mysterious hold over her. Jude is nursing her own revenge fantasy, but she needs Miller''s help, and in exchange, Miller wants Jude to help him with an unspeakable crime. Alone and out-gunned, Poe hopes he can save Jude from herself, make sense of his past, and navigate a torturous internal landscape he calls hell''s half acre.', DATE '2026-03-05', DATE '2026-03-22');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (22, '9789040000000', 'Muis', 4, 'Anthos', 2011, 7.27, 40, 'Elizabeth en haar zestienjarige dochter Shelley, beiden slachtoffer van dagelijkse pesterijen en psychologische mishandeling, besluiten zich terug te trekken in Honeysuckle Cottage. In dit mooie en idyllische arbeidershuisje op het Engelse platteland denken ze eindelijk hun problemen achter zich te kunnen laten. Ze wanen zich veilig in hun kleine wereldje vol boeken en muziek. Maar op een nacht gebeurt er iets dramatisch waardoor er iets in Shelley knapt. Muis is een meeslepend psychologisch drama over een sterke moeder-dochterband. Deze thriller stelt scherpe en uitdagende morele kwesties aan de kaak. De rechten zijn verkocht aan dertien landen.', DATE '2026-03-08', DATE '2026-04-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (23, '9780590000000', 'There''s a Hippie on the Highway', 4, 'HarperCollins Publishers Ltd', 1972, 4.56, 34, 'It seemed like a good idea at the time to ex-paratroop sergeant Harry Mitchell, home after three years in the deadly jungles of Vietnam. Head south to Florida, get a summer job, soak up some sun, relax a bit. But when he got to Paradise City he found himself drawn into a lethal set-up where dumped corpses, smuggling operations, over-ambitious cops, hired killers and a sexy little double-crosser called Nina combined to make life very unhealthy. It was just as well for Harry Mitchell that he''d learned to look after himself in Vietnam...', DATE '2026-03-11', DATE '2026-04-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (24, '9789460000000', 'Tweestrijd', 4, 'Verbum Crime', 2012, 7.58, 43, 'Hanna''s wereldje is perfect. Voor de buitenwereld althans, want al vanaf het begin van haar huwelijk met de rijke en gerenommeerde gynaecoloog Axel Kolman wordt haar leven beheerst door intimidatie, bedreigingen en geweld. Sonja, ongedwongen en zelfstandig, werkt als rechercheur bij de Utrechtse politie. Ze is getrouwd met Maurice, een advocaat die leeft voor zijn werk en niets liever wil dan een gezin stichten, iets wat zijzelf helemaal niet ziet zitten. Als Sonja en Maurice de villa tegenover die van Hanna en Axel betrekken, raken hun levens ongewild met elkaar verstrengeld, wat een kettingreactie in werking zet, die niet meer te stoppen is. Wanneer Hanna ontdekt dat Axels verleden niet zo brandschoon is als ze altijd gedacht heeft, krijgen de gebeurtenissen een gevaarlijke wending, met ongekende gevolgen.', DATE '2026-03-14', DATE '2026-04-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (25, '9781620000000', 'A Medical Affair', 5, 'Booktrope Publishing', 2013, 22.9, 45, 'After a terrifying life-threatening asthma attack induced by the fumes in her swanky new apartment, Heather Morrison falls for the handsome but very married doctor who saved her. Her "knight in shining armor" turns out to be less of a knight as time goes by and more of a heartbreak waiting to happen. As the saying goes, this is not what the doctor ordered. When the relationship ends, Heather''s life dramatically changes as she finds herself addicted to prescription pills she never needed and her future as a mother in question. Set in the bustling city of New York, A Medical Affair by debut author Anne McCarthy Strauss could be a game changer for many women as it exposes the truth behind her doctor''s behavior and her subsequent filing of a civil suit. Although a work of fiction, A Medical Affair was extensively researched. This is truly a story that must be told.', DATE '2026-03-17', DATE '2026-05-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (26, '9780600000000', 'Indigo', 5, 'iUniverse', 2000, 10.09, 41, 'As a child Hester Wyatt escaped slavery, but now the dark skinned beauty is a dedicated member of Michigan''s Underground railroad, offering other runaways a chance at the freedom she has learned to love. When one of her fellow conductors brings her an injured man to hide, Hester doesn''t hesitate even after she is told about the price on his head. The man in question is the great conductor known as the "Black Daniel" a vital member of the north''s Underground railroad network, but Hester finds him so rude and arrogant, she begins to question her vow to hide him.When the injured and beaten Galen Vachon, aka, the Black Daniel awakens in Hester''s cellar, he is unprepared for the feisty young conductor providing his care. As a member of one of the wealthiest free Black families in New Orleans, Galen has turned his back on the lavish living he is accustomed to in order to provide freedom to those enslaved in the south. However, as he heals he cannot turn his back on Hester Wyatt. Her innocence fills him like a breath of fresh air and he is determined to make her his, but traitors have to be found, slave catchers have to be routed and Hester''s refusal to trust her own heart have to be overcome before she and Galen can find the freedom only love can bring.(back cover)', DATE '2026-03-20', DATE '2026-05-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (27, '9781450000000', 'Lost and Found', 5, 'Createspace Independent Publishing Platform', 2011, 6.37, 11, 'Emi Lost & Found series - Winner of the Best Happily Ever After of 2013 - HEA Bookshelf "There was true depth to the story and the characters that moved me and emotionally gutted me. I was so taken by Nate and Emi''s love for each other. It''s the kind of love that few have and many desire but never get to experience." - Megan, Reading Books Like a Boss Independent and sensitive, idealistic and hopeful, Emi Hennigan lives her life with optimism and an open mind. Between sharing a tiny Manhattan apartment with her fun-loving roommate and spending most of her free time with her heart-breaker friend, Emi''s seen enough failed relationships to know what to avoid in her quest to find her true love. Not only that, but a single moment from her past lingers in her mind, setting high expectations for every man she dates. Emi''s best friend, artist and hopeless romantic Nate Wilson, has been her closest companion all of their adult lives. After swearing off love with Emi in a silly high school pact, Nate has been seeing other women in hopes of finding one that evokes stronger feelings than the ones he''s been harboring for Emi since he was a teen. Over the span of a year, boundaries are crossed, feelings are confessed, and their unique friendship begins to blossom into something more. Through Nate''s eyes, an atypical romance unfolds, disrupting the comfortable safe haven their friendship has provided. With a promising future ahead of them both, fate intervenes to bring two soul mates together. Photography and cover design by Christi Allen Curtis, assisted by Katrina Boone', DATE '2026-03-23', DATE '2026-05-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (28, '9780980000000', 'Shackles of Honor', 5, 'Distractions Ink', 2009, 86.74, 28, 'Cassidy Shea''s life was nothing if not serene. Loving parents and a doting brother provided happiness and innocent hope as life''s experience. Yes-life was blissful at Cassidy''s beloved home-Terrill. Still, for all Terrill''s beauty and tranquility, ever there was something intangible and evasive lurking in the shadows. And though Cassidy wasted little worry on it, still she sensed its existence-looming as a menacing fate bent on ruin. And when a dark stranger appeared, Cassidy could no longer ignore the ominous whispers of the secrets surrounding her. Mason Carlisle, an angry, unpredictable man, materialized-with Cassidy''s black fate at his heels. Thus, thrust into a world completely unknown to her, Cassidy found herself trapped-wandering in a labyrinth of mystery and concealments. Serenity was vanquished-and with it her dreams. Yet, were the secrets so cautiously kept from Cassidy-were they indeed the cloth, the very flax from which her dreams were spun-from which eternal bliss would be woven?', DATE '2026-03-26', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (29, '9780450000000', 'The Bargain', 5, 'Signet Book', 1999, 3.28, 38, 'The Bargain is an expansion and rewriting of The Would-Be Widow To keep her fortune, a beautiful heiress impulsively weds a penniless officer dying of wounds received at Waterloo. But when the blasted man hasn''t the grace to die, she suddenly finds herself with a healthy, vibrant husband who wants to renegotiate the terms of their bargain -- and ultimately possess the heart of his bewildered bride...', DATE '2026-03-29', DATE '2026-04-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (30, '9780820000000', 'The Eternal Highlander', 5, 'Zebra', 2005, 5.68, 26, 'Cathal MacNachton and Connall MacAdie are cousins bound by far more than blood ties and the rugged Highland landscape their clan calls home. The ancient curse of their ancestry has fated them to live by night with an unquenchable thirst that neither can tame. The only thing that can save their souls is marriage to Outsiders--mortals whose untainted blood will weaken the curse in their children and break the chains of fear that have made their clan a breed apart.Bridget Callan and Eva Caxton are the women who will shape the clan''s destiny. Marriage to these strange and mysterious men will rescue each of them from desperate circumstances--and draw them into a web of danger, desire, and intrigue. . .', DATE '2026-01-01', DATE '2026-01-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (31, '9780490000000', 'A Tale of the Western Plains', 6, 'Dover Publications', 2006, 9.1, 47, 'In this story, Henty crafts a rousing adventure drawing on real life cowboy stories. "In treating cowboy life", he tells us, "indeed, it may well be said that truth is stranger than fiction". Henty accurately describes the life of the true American frontiersmen -- mining, hunting, lumberjacking, cattle ranching, trapping, fighting hostile Indian tribes, transporting the reader back to the early days of the Wild West with enough mystery thrown in to capture the reader''s imagination.', DATE '2026-01-04', DATE '2026-01-26');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (32, '9780300000000', 'Cross of Iron', 6, 'Cassell military', 1999, 3.42, 28, 'Cross of Iron is the thrilling story of a German platoon cut off far behind Russian lines in the second half of World War II. A resourceful and cynical commander somehow manages to coax his men through the bitter hand-to-hand fighting in forests, trenches and city streets until eventually they regain the German lines. But safety is only temporary. After the tension of waiting for the last overwhelming Russian advance the platoon is forced into futile counter-attacks and murderous house-to-house fighting until its final decimation becomes inevitable.A modern classic of war fiction both as a book and a film, this is a strikingly realistic story of action on the Eastern Front, where the grimness of combat seems to have neither pity nor end.Author Willi Heinrich (1920-2005) served in the heavily mauled 101st Jager Division, and was himself wounded five times during the war.Cross of Iron was also made into a film of the same name by Sam Peckinpah in 1977.', DATE '2026-01-07', DATE '2026-02-05');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (33, '9780780000000', 'Iron Lace', 6, 'Mira Books', 2005, 3.62, 36, 'When Aurore Gerritsen watched her lover kill her father, it was just one act of violence in a long chain of dramatic events.Years later, behind the iron lace gates of wealthy New Orleans, beneath the veneer of her society name, linger secrets that Aurore Gerritsen has hidden for a lifetime, and truths that threaten to change forever the lives of her unsuspecting family. Now, as Aurore faces her own mortality, she needs to reveal those secrets that have haunted her for so many years.Aurore seeks out Phillip Benedict and asks him to tell her story. He''s intrigued, but wonders why the matriarch of a prominent white family would choose to confess her sins to an outspoken black journalist.Finally Phillip agrees, but though he thinks he''s ready for anything she might say, the truth is that nothing can prepare him for the impact of Aurore''s shocking revelations.', DATE '2026-01-10', DATE '2026-02-15');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (34, '9781840000000', 'Madame', 6, 'Canongate U.S.', 2004, 4.09, 10, 'The comic "sentimental education" of a schoolboy who falls in love with his French teacher. Madame is an unexpected gem: a novel about Poland during the grim years of Soviet-controlled mediocrity, which nonetheless sparkles with light and warmth.Our young narrator-hero is suffering through the regulated boredom of high school when he is transfixed by a new teacher --an elegant "older woman" (she is thirty-two) who bewitches him with her glacial beauty and her strict intelligence. He resolves to learn everything he can about her and to win her heart.In a sequence of marvelously funny but sobering maneuvers, he learns much more than he expected to--about politics, Poland, the Spanish Civil War, and his own passion for theater and art--all while his loved one continues to elude him. Yet without his realizing it, his efforts--largely bookish and literary--to close in on Madame are his first steps to liberation as an artist. Later, during a stint as a teacher-in-training in his old school, he discovers that he himself has become a legendary figure to a new generation of students, and he begins to understand the deceits and blessings of myth, and its redemptive power.A winning portrait of an artist as a young man, Madame is at the same time a moving, engaging novel about strength and weakness, first love, and the efforts we make to reconcile, in art, the opposing forces of reason and passion.', DATE '2026-01-13', DATE '2026-02-25');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (35, '9780720000000', 'Strumpet City', 6, 'Gill', 2006, 3.37, 41, 'Set in Dublin during the Lockout of 1913, Strumpet City is a panoramic novel of city life. It embraces a wide range of social milieux, from the miseries of the tenements to the cultivated, bourgeois Bradshaws. It introduces a memorable cast of characters: the main protagonist, Fitz, a model of the hard-working, loyal and abused trade unionist; the isolated, well-meaning and ineffectual Fr O''Connor; the wretched and destitute Rashers Tierney. In the background hovers the enormous shadow of Jim Larkin, Plunkett''s real-life hero.Strumpet City''s popularity derives from its realism and its naturalistic presentation of traumatic historical events. There are clear heroes and villians. The book is informed by a sense of moral outrage at the treatment of the locked-out trade unionists, the indifference and evasion of the city''s clergy and middle class and the squalor and degradation of the tenement slums.', DATE '2026-01-16', DATE '2026-03-07');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (36, '9780340000000', 'The Escape', 6, 'Hodder Children''s Books', 2009, 1.45, 15, 'Summer, 1940.Hitler''s army is advancing towards Paris, and millions of French civilians are on the run.Amidst the chaos, two British children are being hunted by German agents.British spy Charles Henderson tries to reach them first, but he can only do it with the help of a twelve-year-old French orphan.The British secret service is about to discover that kids working undercover will help to win the war.For official purposes, these children do not exist.', DATE '2026-01-19', DATE '2026-03-17');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (37, '9780620000000', 'All the Lovely Bad Ones', 7, 'Clarion Books', 2008, 6.09, 26, 'Travis and his sister, Corey, can t resist a good trick. When they learn that their grandmother''s quiet Vermont inn, where they re spending the summer, has a history of ghost sightings, they decide to do a little haunting of their own. Before long, their supernatural pranks have tourists flocking to the inn, and business booms. But Travis and Corey soon find out that they aren''t the only ghosts at Fox Hill Inn. Their thoughtless games have awakened something dangerous, something that should have stayed asleep. Restless, spiteful spirits swarm the inn, while a dark and terrifying presence stalks the halls and the old oak grove on the inn s grounds. Only Travis and Corey can lay to rest the ghosts they''ve stirred. This means discovering the secret of Fox Hill and the horrors visited on its inhabitants years before... Once again, Mary Downing Hahn has created a chilling and gripping ghost story in the tradition of The Old Willis Place, Witch Catcher, and Deep and Dark and Dangerous.', DATE '2026-01-22', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (38, '9780100000000', 'Blackwood Farm', 7, 'Arrow books', 2003, 2.76, 30, 'Lestat is back, saviour and demon, presiding over a gothic story of family greed and hatred through generations, a terrifying drama of blood lust and betrayal, possession and matricide. Blackwood Farm with its grand Southern mansion, set among dark cypress swamps in Louisiana, harbours terrible blood-stained secrets and family ghosts. Heir to them all is Quinn Blackwood, young, rash and beautiful, himself a ''bloodhunter'' whom Lestat takes under his wing. But Quinn is in thrall not only to the past and his own appetites but, even more dangerously, to a companion spirit, a ''goblin'' succubus who could destroy him and others. Only the unearthly power of Lestat combined with the earthly powers of the Mayfair clan could hope to save Quinn from himself and his ghosts, or to rescue the doomed girl Quinn loves from her own mortality. Shocking, savage and richly erotic, this novel with the deceptively gentle title bring us Anne Rice at her most powerfully disturbing. Here are vampires and witches, men and women, demons and a doppelganger, caught up in a maelstrom of death and destruction, blood and fire, cruelty and fate.', DATE '2026-01-25', DATE '2026-01-31');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (39, '9780060000000', 'Die for Me', 7, 'HarperTeen', 2011, 3.16, 37, 'In the City of Lights, two star-crossed lovers battle a fate that is destined to tear them apart again and again for eternity.When Kate Mercier''s parents die in a tragic car accident, she leaves her life--and memories--behind to live with her grandparents in Paris. For Kate, the only way to survive her pain is escaping into the world of books and Parisian art. Until she meets Vincent.Mysterious, charming, and devastatingly handsome, Vincent threatens to melt the ice around Kate''s guarded heart with just his smile. As she begins to fall in love with Vincent, Kate discovers that he''s a revenant--an undead being whose fate forces him to sacrifice himself over and over again to save the lives of others. Vincent and those like him are bound in a centuries-old war against a group of evil revenants who exist only to murder and betray. Kate soon realizes that if she follows her heart, she may never be safe again.', DATE '2026-01-28', DATE '2026-02-10');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (40, '9780430000000', 'Real Vampires Have Curves', 7, 'Berkley Books', 2007, 4.18, 14, 'What - did you think all vamps were pale, thin and brooding? Don''t I wish. Gloriana St. Clair is an eternally "full-figured" vampire-she just happened to be bloating when a sexy Scotsman sank his teeth into her. She and said Scot- Angus Jeremiah Campbell III, aka Jeremy Blade-have been on and off again for centuries, currently off. A couple hundred years has taught them how to press each other''s buttons-in good ways and bad. Glory''s headed for Austin and a new business venture: Vintage Vamp''s Emporium. After all, she loves clothes, and she is an antique. Only problem is, there''s a billionaire techno-freak vampire hunter on the loose. Blade''s in total he- vampire mode, and wants Glory to move in with him so he can "protect" her. But it''s time for this vamp to explore her own powers.', DATE '2026-01-31', DATE '2026-02-20');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (41, '9781540000000', 'The Vampire''s Widow', 7, 'Createspace Independent Publishing Platform', 2017, 13.3, 24, 'The Vampire''s Widow . A novella. Second Edition October 2017She overcomes one horrific world, only to enter another. Livia''s abusive husband, Eddie, is always cheating on her but things get worse when he unknowingly hooks up with a vampire. When FBI Agent Cruz arrives in town, hot on the vampire''s trail, she quickly skips town, leaving a clueless and infected Eddie to fend for himself. Already violent, Eddie soon grows more unstable until a confrontation with the police leaves him shot and buried. Livia''s relief is short-lived however when she discovers that even Eddie''s death can''t free her. Is Eddie back, or is Livia going crazy?', DATE '2026-02-03', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (42, '9781910000000', 'Undead', 7, 'Chicken House', 2011, 2.61, 15, 'When their ski-coach pulls up at a cafe, new girl Bobby and rebel Smitty stay behind. They hardly know each other, but that changes when they see the others coming back. Something has happened to them - something bad. Soon, only a pair of double doors stands between those on the bus and their ex-friends outside.', DATE '2026-02-06', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (43, '9780010000000', 'Little Manfred', 8, 'HarperCollins Children''s Books', 2011, 2.2, 41, 'The heart-lifting, heartbreaking new story by Michael Morpurgo, the nation''s favourite storyteller. In the Imperial War Museum is a wooden Dachshund, carved by a German prisoner of war for the children of the British family with which he stayed after the fighting ended. This is the story of how it got there! When the Bismarck sinks, one of the only German survivors is taken on board a British ship as a prisoner of war. Sent to live with a host family, Walter must adapt to a new way of life, in the heart of an enemy country. Gradually, though, he finds a friend in ten-year-old Grace. So when the time finally comes to go back to Germany, it''s an emotional parting, with Walter leaving Grace with only a carved wooden dog to remember him by. The question is, will Walter and Grace ever meet again? In 1966, with the World Cup coming to Britain, that opportunity may just have come along!', DATE '2026-02-09', DATE '2026-03-22');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (44, '9780440000000', 'My Name Is Sus5an Smith: The 5 Is Silent', 8, 'Laurel Leaf', 1993, 3.29, 12, 'A powerful coming-of-age story from the award-winning author of The Romantic Obsessions and Humiliations of Annie Sehlmeier. Bored with her life in Utah, Sus5an Smith (the 5 is silent) jumps at the chance to move to Boston and work on her art. But she finds herself in an emotional dilemma, when she is attracted to her newly-divorced uncle--who''s twice her age. for Young Adults.', DATE '2026-02-12', DATE '2026-04-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (45, '9780690000000', 'Shiloh Season', 8, 'Aladdin Paperbacks', 2000, 6.2, 39, 'In Shiloh Season, Shiloh finally belongs to Marty, but the dog''s original owner, Judd Travers, has started drinking again--and for Judd Travers, beer and a gun are a dangerous combination. Marty''s family seems to be the target of Judd''s rage.', DATE '2026-02-15', DATE '2026-04-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (46, '9780910000000', 'The Lion''s Paw', 8, 'Mickler House Publishers', 1994, 32.12, 45, 'Ben, Penny and Nick are running away. Searching for them are Ben''s uncle, the Coast Guard, everybody in Florida. Will they make good their escape? And will they find the Lion''s Paw?', DATE '2026-02-18', DATE '2026-04-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (47, '9780570000000', 'The Mirror Image Ghost', 8, 'Faber Faber', 2000, 2.91, 36, 'Shortlisted for the Children''s Book Award 1995, this ghost story centres around Lisa, who is sure that she has seen a ghost in the reflection of her mother''s bedroom mirror. She finds herself drawn into the dramatic events of the world entered into through the mirrors.', DATE '2026-02-21', DATE '2026-02-25');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (48, '9780680000000', 'The Salamander Room', 8, 'Dragonfly Books', 1994, 7.42, 32, 'A boy finds a salamander in the woods and imagines the many things he can do to turn his room into a perfect salamander home. Together, Anne Mazer and Steve Johnson have created a woodland paradise that any salamander would love to share with a child.', DATE '2026-02-24', DATE '2026-03-07');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (49, '9781400000000', 'Batman & Robin, Vol. 2: Batman vs. Robin', 9, 'DC Comics', 2010, 15.82, 12, 'Grant Morrison continues his habit of teaming up with A-list, critically acclaimed artists by joining Cameron Stewart (Seven Soldiers of Victory: Manhattan Guardian) and Andy Clarke (Batman: Face the Face) for the next exciting chapter of the adventures of the new Dynamic Duo!The new Batman and Robin uncover clues involving the mysterious death of Bruce Wayne before facing off against each other in a heated battle instigated by Robin''s mother that both heroes will regret - if they live through it! Featuring a 3-issues storyline that ties into the best-selling Blackest Night event titled "Blackest Knight," this new collection is a must-have for both new readers and longtime fans of Grant Morrison''s Batman epic as the superstar writer unveils more of his genre-defying masterplan!Collecting: Batman & Robin 7-12', DATE '2026-02-27', DATE '2026-03-17');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (50, '9780550000000', 'Calling Dr. Laura', 9, 'Mariner Books', 2013, 5.91, 31, 'When Nicole Georges was two years old, her family told her that her father was dead. When she was twenty-three, a psychic told her he was alive. Her sister, saddled with guilt, admits that the psychic is right and that the whole family has conspired to keep him a secret. Sent into a tailspin about her identity, Nicole turns to radio talk-show host Dr. Laura Schlessinger for advice.Packed cover-to-cover with heartfelt and disarming black-and-white illustrations, Calling Dr. Laura tells the story of what happens to you when you are raised in a family of secrets, and what happens to your brain (and heart) when you learn the truth from an unlikely source. Part coming-of-age and part coming-out story, Calling Dr. Laura marks the arrival of an exciting and winning new voice in graphic literature.', DATE '2026-03-02', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (51, '9780760000000', 'The Melancholy of Haruhi Suzumiya, Vol. 4', 9, 'Yen Press', 2009, 2.88, 28, 'When the SOS Brigade receives an urgent message that the Computer Research Society''s president has gone missing, Haruhi confidently promises to locate him, and the SOS Brigade is off! Of course, they have no idea where to start... Is the new SOS Brigade insignia that Haruhi designed to blame for all of this???', DATE '2026-03-05', DATE '2026-04-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (52, '9780350000000', 'Tsubasa: RESERVoir CHRoNiCLE, Vol. 05', 9, 'Del Rey', 2005, 1.22, 27, 'THE END OF A FAIRY TALEFollowing the trail of the stolen children of Spirit Town, Sakura is captured at the forbidden castle, where she encounters the golden-haired ghost! Syaoran and his friends - the sociable magician Fai D. Flowright, the master swordsman Kurogane, and the odd creature Mokona - must now penetrate the ancient stronghold in order to rescue Sakura and the missing children. Will they finally uncover the truth behind the legend of Princess Emerald? And will they recover another fragment of Sakura''s lost memory?', DATE '2026-03-08', DATE '2026-04-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (53, '9781420000000', 'Vampire Knight, Vol. 1', 9, 'VIZ Media', 2007, 1.79, 27, 'Yuki Cross has no memory of her past prior to the moment she was saved from a vampire attack ten years ago. She was adopted by the headmaster of Cross Academy, and now works alongside Zero to guard the Academy''s secret. Cross Adademy is attended by two groups of students: the Day Class and the Night Class. At twilight, when the students of the Day Class return to their dorm, they cross paths with the Night Class on their way to school. Yuki Cross and Zero Kiryu are the Guardians of the school, protecting the Day Class from the Academy''s dark secret: the Night Class is full of vampires!', DATE '2026-03-11', DATE '2026-04-26');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (54, '9781630000000', 'Wayward, Vol. 2: Ties That Bind', 9, 'Image Comics', 2015, 3.47, 25, 'After the traumatizing finale of volume one, everything has changed for our supernatural teens. Who is Ohara and how does she fit into the great pattern of destiny and power that will change Japan forever? Jim Zub (Conan/Red Sonja, Samurai Jack) and Steve Cummings (Deadshot, Legends of the Dark Knight) continue their supernatural spectacle that combines the camaraderie and emotion of shows like Buffy with Japan''s engaging culture and mythic monsters. This volume includes design artwork by artist Steve Cummings and profiles on mythical creatures by noted monster researcher Zack Davisson.Collects Wayward #6-10.', DATE '2026-03-14', DATE '2026-05-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (55, '9788480000000', 'Antes Que Anochezca', 10, 'TusQuets', 2011, 10.5, 47, 'This shocking personal and political memoir from one of the most visionary writers to emerge from Castro''s Cuba recounts Arenas'' stunning odyssey--from his poverty-stricken childhood through his suppression as a writer and imprisonment as a homosexual to his flight to America and subsequent life and death in New York. A New York Times Best Book of 1993.', DATE '2026-03-17', DATE '2026-05-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (56, '9780970000000', 'Diary of a Lost Girl: The Autobiography of Kola Boof', 10, 'Door of Kush', 2006, 73.73, 24, 'Kola Boof''s long awaited autobiography "Diary of a Lost Girl" is nothing less than magnificent. Many will be spellbound by more than 90 pages detailing her terrifying experience as Osama Bin Laden''s former mistress, but the Sudanese-born Novelist/Poet writes even more profoundly about the hardships of being vaginally circumcised, about witnessing her birth parents killed in her presence as a small child, about slavery and Arabism in Sudan, about being adopted and raised in the U.S. by African Americans, about her quest for true love, and in one particularly daring chapter, about her hopes for the future of her sons. Add to that years of psychiatric treatment, a struggle with manic anger and quite a few daring romances other than Bin Laden and you''ve got the perfect ingredients for a feature film.Critically acclaimed for her powerful novels "Flesh and the Devil", "Pure Nigger Evil" and the classic short story collection, "Long Train to the Redeeming Sin"...I''m now convinced that there''s no way Kola Boof could ever create a fictional character in one of her novels that is more glamorous, sad, enigmatic and intriguing than she herself is in real life.', DATE '2026-03-20', DATE '2026-03-22');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (57, '9780370000000', 'Fierce Attachments: A Memoir', 10, 'Farrar, Straus and Giroux', 2005, 12.85, 43, 'In this deeply etched and haunting memoir, Vivian Gornick tells the story of her lifelong battle with her mother for independence. There have been numerous books about mother and daughter, but none has dealt with this closest of filial relations as directly or as ruthlessly. Gornick''s groundbreaking book confronts what Edna O''Brien has called "the prinicpal crux of female despair": the unacknowledged Oedipal nature of the mother-daughter bond.Born and raised in the Bronx, the daughter of "urban peasants," Gornick grows up in a household dominated by her intelligent but uneducated mother''s romantic depression over the early death of her husband. Next door lives Nettie, an attractive widow whose calculating sensuality appeals greatly to Vivian. These women with their opposing models of femininity continue, well into adulthood, to affect Gornick''s struggle to find herself in love and in work.As Gornick walks with her aged mother through the streets of New York, arguing and remembering the past, each wins the reader''s admiration: the caustic and clear-thinking daughter, for her courage and tenacity in really talking to her mother about the most basic issues of their lives, and the still powerful and intuitively-wise old woman, who again and again proves herself her daughter''s mother.Unsparing, deeply courageous, Fierce Attachments is one of the most remarkable documents of family feeling that has been written, a classic that helped start the memoir boom and remains one of the most moving examples of the genre.', DATE '2026-03-23', DATE '2026-04-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (58, '9780200000000', 'James Joyce', 10, 'Oxford University Press, USA', 1983, 10, 31, 'Although several biographers have thrown themselves into the breach since this magisterial book first appeared in 1959, none have come close to matching the late Richard Ellmann''s achievement. To be fair, Ellmann does have some distinct advantages. For starters, there''s his deep mastery of the Irish milieu--demonstrated not only in this volume but in his books on Yeats and Wilde. He''s also an admirable stylist himself--graceful, witty, and happily unintimidated by his brilliant subjects. But in addition, Ellmann seems to have an uncanny grasp on Joyce''s personality: his reverence for the Irishman''s literary accomplishment is always balanced by a kind of bemused affection for his faults. Whether Joyce is putting the finishing touches on Ulysses, falling down drunk in the streets of Trieste, or talking dirty to his future wife via the postal service, Ellmann''s account always shows us a genius and a human being--a daunting enough task for a fiction writer, let alone the poor, fact-fettered biographer. Richard Ellmann has revised and expanded his definitive work on Joyce''s life to include newly discovered primary material, including details of a failed love affair, a limerick about Samuel Beckett, a dream notebook, previously unknown letters, and much more.', DATE '2026-03-26', DATE '2026-04-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (59, '9781850000000', 'Nikolai Gogol', 10, 'Penguin Classics', 2011, 6.05, 36, 'Nikolai Gogol was one of the great geniuses of nineteenth century Russian literature, with a command of the irrational unmatched by any writer before or since. His strange tales, though often read as forceful demands for social change, were displays of the fantasies of the human spirit. In this ideal marriage of subject and critic, Nabokov analyses his endlessly inventive compatriot, focusing on the masterpieces Dead Souls, The Overcoat and The Government Inspector.Misunderstood by his contemporaries, mishandled by theatre directors and ending his life mistreated by doctors - with medicinal leeches hanging from his exceptional nose - it took Nabokov to give Gogol, ''the oddest Russian in Russia'', the critical biography he and his singular, brilliant work deserve.', DATE '2026-03-29', DATE '2026-04-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (60, '9781580000000', 'No Hurry to Get Home: The Memoir of the New Yorker Writer Whose Unconventional Life and Adventures Spanned the Century', 10, 'Seal Press', 2000, 2.31, 27, 'Emily Hahn was a woman ahead of her time, graced with a sense of adventure and a gift for living. Born in St. Louis in 1905, she crashed the all-male precincts of the University of Wisconsin geology department as an undergraduate, traveled alone to the Belgian Congo at age 25, was the concubine of a Chinese poet in Shanghai, bore the child of the head of the British Secret Service before World War II, and finally returned to New York to live and write in Greenwich Village. In this memoir, first published as essays in The New Yorker, Hahn writes vividly and amusingly about the people and places she came to know and love -- with an eye for the curious and a heart for the exotic.', DATE '2026-01-01', DATE '2026-01-31');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (61, '9780070000000', 'At Dawn We Slept: The Untold Story of Pearl Harbor', 11, 'The McGraw-Hill Publishing Company, Inc.', 1981, 5.52, 42, 'Decades after the attack that plunged America into WWII, At Dawn We Slept remains the greatest account of Pearl Harbor ever written. This gripping study scrupulously reconstructs the Japanese attack, from its conception (less than a year before the actual raid) to its lightning execution; & it reveals the true reason for the American debacle: the insurmountable disbelief in the Japanese threat that kept America from heeding advance warnings & caused leaders to ignore evidence submitted by our own intelligence sources. Based on 37 years of intense research & countless interviews, & incorporating previously untranslated documents, At Dawn We Slept is history with the dramatic sweep of a martial epic.', DATE '2026-01-04', DATE '2026-02-10');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (62, '9780330000000', 'Crying Wolf: The Return of War to Chechnya', 11, 'Pan Books', 2001, 3.7, 32, 'Written in passionate prose, this is the story of the one million Chechens who, following the collapse of the Soviet Union, found themselves cast as the enemy of the new Russian state. Compelled to assert their freedom and individualism, they faced the huge Russian army in a one-sided war which destroyed their land, their homes, and their families. This updated account also covers the role of Vladimir Putin in the continuing struggle.', DATE '2026-01-07', DATE '2026-02-20');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (63, '9780750000000', 'Ghosts And Gravestones Of Haworth', 11, 'History Press (SC)', 2006, 6.84, 18, 'Takes you on a tour of Haworth''s dark and ghostly side: meet the ghost of Room 7 at the Old White Lion, the Grey Lady of Weavers Restaurant, and Ponden Hall''s harbinger of doom, Old Greybeard. This title also helps the reader to tour the famous graveyard, in use for over 700 years ago and believed to house over 40,000 souls.', DATE '2026-01-10', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (64, '9780960000000', 'One World Order', 11, 'Bridger House Publishers Inc', 2003, 15.21, 42, 'The enemy in washington is more to be feared than the enemy in Moscow Communism did not destroy tariff protection created by George Washington. Communism did not force the United States to adopt graduated income tax. Communism did not create the Federal Reserve Board. Communism did not force the United Nations on America. Communism did not take away the Panama Canal away from the American people. Communism did not create the Global 2000 report mass genocide plan. It is socialism that has brought forth these evils upon the United States. One World Order: Socialist Dictatorship tells how this was, and is being accomplished.', DATE '2026-01-13', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (65, '9780580000000', 'The Americans: A Social History of the United States, 1587-1914', 11, 'G.P. Putnam''s Sons (NY)', 1969, 3.42, 12, 'AcknowledgmentsIntroductionPrologueThe Big Water & the Big WoodsOutlanderslandAt Home AbroadThirteen ProsperThe American, This New Man...Ideas & the Almighty DollarA Chromo CivilizationThe Midway AgeNotesQuoted SourcesIndex', DATE '2026-01-16', DATE '2026-01-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (66, '9780230000000', 'The Culture of Sensibility: Sex and Society in Eighteenth-Century Britain', 11, 'University of Chicago Press', 1996, 36.13, 21, 'G. J. Barker-Benfield documents the emergence of the culture of sensibility that transformed British society of the eighteenth century. His account focuses on the rise of new moral and spiritual values and the struggle to redefine the group identities of men and women. Drawing on the full spectrum of eighteenth-century thought from Adam Smith to John Locke, from the Earl of Shaftesberry to Dr. George Cheyne, and especially Mary Wollstonecraft, Barker-Benfield offers an innovative and compelling way to understand how Britain entered the modern age.', DATE '2026-01-19', DATE '2026-01-26');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (67, '9780540000000', 'A Crack in Creation: Gene Editing and the Unthinkable Power to Control Evolution', 12, 'Houghton Mifflin Harcourt', 2017, 16.69, 20, 'Two scientists explore the potential of a revolutionary genetics technology capable of easily and affordably manipulating DNA in human embryos to prevent specific diseases, addressing key concerns about related ethical and societal repercussions.', DATE '2026-01-22', DATE '2026-02-05');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (68, '9780670000000', 'Bee Time: Lessons from the Hive', 12, 'Harvard University Press', 2016, 16.98, 47, 'Being among bees is a full-body experience, Mark Winston writes--from the low hum of tens of thousands of insects and the pungent smell of honey and beeswax, to the sight of workers flying back and forth between flowers and the hive. The experience of an apiary slows our sense of time, heightens our awareness, and inspires awe. Bee Time presents Winston''s reflections on three decades spent studying these creatures, and on the lessons they can teach about how humans might better interact with one another and the natural world.Like us, honeybees represent a pinnacle of animal sociality. How they submerge individual needs into the colony collective provides a lens through which to ponder human societies. Winston explains how bees process information, structure work, and communicate, and examines how corporate boardrooms are using bee societies as a model to improve collaboration. He investigates how bees have altered our understanding of agricultural ecosystems and how urban planners are looking to bees in designing more nature-friendly cities.The relationship between bees and people has not always been benign. Bee populations are diminishing due to human impact, and we cannot afford to ignore what the demise of bees tells us about our own tenuous affiliation with nature. Toxic interactions between pesticides and bee diseases have been particularly harmful, foreshadowing similar effects of pesticides on human health. There is much to learn from bees in how they respond to these challenges. In sustaining their societies, bees teach us ways to sustain our own.', DATE '2026-01-25', DATE '2026-02-15');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (69, '9780390000000', 'How to Lie with Statistics', 12, 'W. W. Norton & Company', 1982, 11.55, 13, 'Darrell Huff runs the gamut of every popularly used type of statistic, probes such things as the sample study, the tabulation method, the interview technique, or the way the results are derived from the figures, and points up the countless number of dodges which are used to fool rather than to inform.', DATE '2026-01-28', DATE '2026-02-25');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (70, '9780870000000', 'Return to Wild America: A Yearlong Search for the Continent''s Natural Soul', 12, 'North Point Press', 2005, 5.2, 12, 'In 1953, birding guru Roger Tory Peterson and noted British naturalist James Fisher set out on what became a legendary journey-a one hundred day trek over 30,000 miles around North America. They traveled from Newfoundland to Florida, deep into the heart of Mexico, through the Southwest, the Pacific Northwest, and into Alaska''s Pribilof Islands. Two years later, Wild America, their classic account of the trip, was published.On the eve of that book''s fiftieth anniversary, naturalist Scott Weidensaul retraces Peterson and Fisher''s steps to tell the story of wild America today. How has the continent''s natural landscape changed over the past fifty years? How have the wildlife, the rivers, and the rugged, untouched terrain fared? The journey takes Weidensaul to the coastal communities of Newfoundland, where he examines the devastating impact of the Atlantic cod fishery''s collapse on the ecosystem; to Florida, where he charts the virtual extinction of the great wading bird colonies that Peterson and Fisher once documented; to the Mexican tropics of Xilitla, which have become a growing center of ecotourism since Fisher and Peterson''s exposition. And perhaps most surprising of all, Weidensaul finds that much of what Peterson and Fisher discovered remains untouched by the industrial developments of the last fifty years. Poised to become a classic in its own right, Return to Wild America is a sweeping survey of the natural soul of North America today.', DATE '2026-01-31', DATE '2026-03-07');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (71, '9780320000000', 'The Animal Dialogues: Uncommon Encounters in the Wild', 12, 'Little Brown and Company', 2008, 5.95, 49, 'From one of the finest nature writers at work in America today; a lyrical, dramatic, illuminating tour of the hidden domain of wild animals.Whether recalling the experience of being chased through the Grand Canyon by a bighorn sheep, swimming with sharks off the coast of British Columbia, watching a peregrine falcon perform acrobatic stunts at 200 miles per hour, or engaging in a tense face-off with a mountain lion near a desert waterhole, Craig Childs captures the moment so vividly that he puts the reader in his boots.Each of the forty brief, compelling narratives in The Animal Dialogues focuses on the author''s own encounter with a particular species and is replete with astonishing facts about the species'' behavior, habitat, breeding, and lifespan. But the glory of each essay lies in Childs''s ability to portray the sometimes brutal beauty of the wilderness, to capture the individual essence of wild creatures, to transport the reader beyond the human realm and deep inside the animal kingdom.', DATE '2026-02-03', DATE '2026-03-17');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (72, '9781410000000', 'The Song of the Cardinal', 12, 'Echo Library', 2006, 7.85, 45, 'The Song of the Cardinal, A Love Story. (Illustrated with "camera studies from life by the author." Publisher''s green cloth with paste-on image of a cardinal.)"She had taken possession of the sumac. The location was her selection and he loudly applauded her choice. She placed the first twig, and after examining it carefully, he spent the day carrying her others just as much alike as possible. If she used a dried grass blade, he carried grass blades until she began dropping them on the ground."', DATE '2026-02-06', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (73, '9781590000000', 'Ignore Everybody: and 39 Other Keys to Creativity', 13, 'Portfolio', 2009, 1.45, 44, 'When Hugh MacLeod was a struggling young copywriter living in a YMCA, he started to doodle on the backs of business cards while sitting at a bar. Those cartoons eventually led to a popular blog-gapingvoid.com-and a reputation for pithy insight and humor, in both words and pictures.MacLeod has opinions on everything from marketing to the meaning of life, but one of his main subjects is creativity. How do new ideas emerge in a cynical, risk-averse world? Where does inspiration come from? What does it take to make a living as a creative person?Ignore Everybody expands on MacLeod''s sharpest insights, wittiest cartoons, and most useful advice. For example:-Selling out is harder than it looks. Diluting your product to make it more commercial will just make people like it less.-If your plan depends on you suddenly being "discovered" by some big shot, your plan will probably fail. Nobody suddenly discovers anything. Things are made slowly and in pain.-Don''t try to stand out from the crowd; avoid crowds altogether. There''s no point trying to do the same thing as 250,000 other young hopefuls, waiting for a miracle. All existing business models are wrong. Find a new one.-The idea doesn''t have to be big. It just has to be yours. The sovereignty you have over your work will inspire far more people than the actual content ever will.After learning MacLeod''s forty keys to creativity, you will be ready to unlock your own brilliance and unleash it on the world.', DATE '2026-02-09', DATE '2026-04-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (74, '9780940000000', 'Memoirs of My Nervous Illness', 13, 'NYRB Classics', 2000, 16.46, 44, 'In 1884, the distinguished German jurist Daniel Paul Schreber suffered the first of a series of mental collapses that would afflict him for the rest of his life. In his madness, the world was revealed to him as an enormous architecture of nerves, dominated by a predatory God. It became clear to Schreber that his personal crisis was implicated in what he called a "crisis in God''s realm," one that had transformed the rest of humanity into a race of fantasms. There was only one remedy; as his doctor noted: Schreber "considered himself chosen to redeem the world, and to restore to it the lost state of Blessedness. This, however, he could only do by first being transformed from a man into a woman...."', DATE '2026-02-12', DATE '2026-04-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (75, '9780790000000', 'Reframing Organizations: Artistry, Choice, and Leadership', 13, 'Jossey-Bass', 2003, 1.64, 47, 'In this third edition of their best-selling classic, authors Lee Bolman and Terrence Deal explain the powerful tool of "reframing." The authors have distilled the organizational literature into a comprehensive approach for looking at situations from more than one angle. Their four frames view organizations as factories, families, jungles, and theaters or temples:The Structural Frame how to organize and structure groups and teams to get resultsThe Human Resource Frame how to tailor organizations to satisfy human needs, improve human resource management, and build positive interpersonal and group dynamicsThe Political Frame: how to cope with power and conflict, build coalitions, hone political skills, and deal with internal and external politicsThe Symbolic Frame how to shape a culture that gives purpose and meaning to work, stage organizational drama for internal and external audiences, and build team spirit through ritual, ceremony, and story', DATE '2026-02-15', DATE '2026-02-20');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (76, '9781120000000', 'Startup Communities: Building an Entrepreneurial Ecosystem in Your City', 13, 'Wiley', 2012, 3.66, 35, 'An essential guide to building supportive entrepreneurial communities"Startup communities" are popping up everywhere, from cities like Boulder to Boston and even in countries such as Iceland. These types of entrepreneurial ecosystems are driving innovation and small business energy. "Startup Communities" documents the buzz, strategy, long-term perspective, and dynamics of building communities of entrepreneurs who can feed off of each other''s talent, creativity, and support.Based on more than twenty years of Boulder-based entrepreneur turned-venture capitalist Brad Feld''s experience in the field?as well as contributions from other innovative startup communities?this reliable resource skillfully explores what it takes to create an entrepreneurial community in any city, at any time. Along the way, it offers valuable insights into increasing the breadth and depth of the entrepreneurial ecosystem by multiplying connections among entrepreneurs and mentors, improving access to entrepreneurial education, and much more.Details the four critical principles needed to form a sustainable startup communityPerfect for entrepreneurs and venture capitalists seeking fresh ideas and new opportunitiesWritten by Brad Feld, a thought-leader in this field who has been an early-stage investor and successful entrepreneur for more than twenty yearsEngaging and informative, this practical guide not only shows you how startup communities work, but it also shows you how to make them work anywhere in the world.', DATE '2026-02-18', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (77, '9780470000000', 'The Bogleheads'' Guide to Investing', 13, 'John Wiley & Sons', 2006, 9.24, 38, 'The Bogleheads'' Guide to Investing is a slightly irreverent, straightforward guide to investing for everyone. The book offers sound, practical advice, no matter what your age or net worth. Bottomline, become a Boglehead and prosper! Originally just the chat-line ruminations of Boglehead founder Taylor Larimore, and Morningstar forum leading cohorts Mel Lindauer and Michael LeBoeuf, their trusted advice has been brewed and distilled into an easy-to-use, need-to-know, no frills guide to building up your own financial well-being - so you can worry less and profit more from the investments you make. Invest like a Boglehead, and let their grassroots investment wisdom guide you down the path of long-term wealth creation and happiness, without all the worries and fuss of stock pickers and day traders. If you face a financial crisis or problem, or simply want to know what is prudent to do with the money you save, the Bogleheads will have the answers you need to help you gain your financial footing and keep it.', DATE '2026-02-21', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (78, '9780280000000', 'Today I''m Alice: Nine Personalities, One Tortured Mind', 13, 'Sidgwick & Jackson Ltd', 2009, 14.36, 44, 'When Alice was a teenager, strange things started happening to her. Hours of her life simply disappeared. In this work she describes her journey from a teenage girl battling anorexia and OCD, drowning the voices with alcohol, to a young woman slipping further and further into mental illness.', DATE '2026-02-24', DATE '2026-03-22');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (79, '9780930000000', 'By This Standard: The Authority of God''s Law Today', 14, 'Institute for Christian Economics', 1991, 13.9, 41, 'God''s Law is Christianity''s tool of dominion. This is where any discussion of God''s law ultimately arrives: the issue of dominion. Ask yourself: Who is to rule on earth, Christ or Satan? Whose followers have the ethically acceptable tool of dominion, Christ''s or Satan''s? What is this tool of dominion, the Biblically revealed law of God, or the law of self-proclaimed autonomous man? Whose word is sovereign, God''s or man''s?Millions of Christians, sadly, have not recognized the continuing authority of God''s law or its many applications to modern society. They have thereby reaped the whirlwind of cultural and intellectual impotence. They implicitly denied the power of the death and resurrection of Christ. They have served as footstools for the enemies of God. But humanism''s free ride is coming to an end. This book serves as an introduction to this woefully neglected topic.', DATE '2026-02-27', DATE '2026-04-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (80, '9780380000000', 'Light in My Darkest Night', 14, 'Avon Books', 1994, 7.55, 15, 'This is the story of the intense despair and spiritual emptiness that threatened Catherine Marshall''s marriage, her health, and her life--and of the devastating discovery that ultimately brought her peace through a new and greater appreciation of God''s love and will.', DATE '2026-03-02', DATE '2026-04-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (81, '9780900000000', 'Reflections', 14, 'Octagon Press, Limited', 1978, 9.75, 10, 'Small in size, but with a powerful punch, Idries Shah''s Reflections is a collection of fables, aphorisms, and statements that challenge the conditioned mind. The book confronts the reader with unaccustomed perspectives and ideas, in an attempt to set the mind free, to see how things really are. As the book''s foreword states, ''Do you imagine that fables exist only to amuse or to instruct, and are based upon fiction? The best ones are delineations of what happens in real life, in the community and in the individual''s mental processes''.', DATE '2026-03-05', DATE '2026-04-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (82, '9781570000000', 'The Art of Happiness', 14, 'Riverhead Hardcover', 1998, 4.35, 49, 'Nearly every time you see him, he''s laughing, or at least smiling. And he makes everyone else around him feel like smiling. He''s the Dalai Lama, the spiritual and temporal leader of Tibet, a Nobel Prize winner, and an increasingly popular speaker and statesman. What''s more, he''ll tell you that happiness is the purpose of life, and that "the very motion of our life is towards happiness." How to get there has always been the question. He''s tried to answer it before, but he''s never had the help of a psychiatrist to get the message across in a context we can easily understand. Through conversations, stories, and meditations, the Dalai Lama shows us how to defeat day-to-day anxiety, insecurity, anger, and discouragement. Together with Dr. Cutler, he explores many facets of everyday life, including relationships, loss, and the pursuit of wealth, to illustrate how to ride through life''s obstacles on a deep and abiding source of inner peace.', DATE '2026-03-08', DATE '2026-05-01');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (83, '9781490000000', 'The Modern Man: A philosophical divagation about the evil banality of daily acts', 14, 'CreateSpace', 2013, 9.33, 41, 'A philosophical divagation about the evil banality of daily acts. With this subtitle, the author dedicates herself to dissect a few hours of a man''s thoughts, feelings and life, in his non-functioning world, which is habitually regulated by tic-tacs, and the consequences of his previous acts.', DATE '2026-03-11', DATE '2026-05-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (84, '9780830000000', 'Victory Over the Darkness', 14, 'Regal Books', 2000, 3.27, 12, 'Ten years ago a breakthrough book launched a ministry that has helped more than one million people overcome this world and win the battle for their hearts and minds. Now Neil Anderson has revised and expanded Victory over the Darkness for a new generation of readers, outlining practical and more productive ways to Christian growth based on Christ''s promise, You will know the truth, and the truth will make you free. Victory Over the Darkness emphasizes the importance of believing and internalizing the cardinal truths of Scripture as a base from which to renew the mind and fend off the attempts of Satan to convince us that we are less than Christ empowers us to be.', DATE '2026-03-14', DATE '2026-03-17');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (85, '9781890000000', 'Judevine: The Complete Poems, 1970-1990', 15, 'Chelsea Green Publishing Company', 1999, 13.03, 15, 'The stage is "Judevine," an imaginary town in northern Vermont. This is a small stage, sometimes cold and darkened, but filled with characters so finely etched that they stand out as clearly as steeples against the sky. David Budbill plunges into the soul of New England to find characters and stories with lessons for anyone wanting to find the intrinsic nature of the region that has been called "all of America''s backyard." These dark, lyrical, funny narrative poems portray the hopes and joys, pains and despair of people who have been bypassed or bruised by the twentieth century. Budbill has written a song of the down-and-out or overlooked, a song of the unsung. This anthem of the rural renaissance is microcosmic in setting, but universal in scope.', DATE '2026-03-17', DATE '2026-03-27');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (86, '9783820000000', 'Pablo Picasso, 1881-1973: Genius of the Century', 15, 'Taschen', 2000, 1.14, 27, 'Pablo Picasso once said, "If there''s something to be stolen, I steal it." Few artists have helped themselves as liberally from the treasures of bygone art. His own legacy is scarcely paralleled in its scope and diversity. Our study of Picasso, the most exhaustive record of his work to date, contains almost 1500 illustrations - from his earliest drawings to the master''s very last painting.', DATE '2026-03-20', DATE '2026-04-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (87, '9781480000000', 'Poetry and Short Stories by a Bipolar Girl', 15, 'Outskirts Press', 2012, 10.23, 37, 'This book was written by a young woman with bipolar disorder, who wrote poems and short stories both in her manic and depressed states.It''s meant to shed some light on bipolar disorder and depression for those who don''t suffer from those things, know someone who does or just want to understand what goes through the mind of someone with mental illness.It''s also meant to show those who go through the same things that they aren''t alone.And while doing all of that, it''s also just a fun book to read.', DATE '2026-03-23', DATE '2026-04-16');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (88, '9780290000000', 'Sculpting in Time', 15, 'University of Texas Press', 1989, 23.88, 34, 'Andrey Tarkovsky, the genius of modern Russian cinema--hailed by Ingmar Bergman as "the most important director of our time"--died an exile in Paris in December 1986. In Sculpting in Time, he has left his artistic testament, a remarkable revelation of both his life and work. Since Ivan''s Childhood won the Golden Lion at the Venice Film Festival in 1962, the visionary quality and totally original and haunting imagery of Tarkovsky''s films have captivated serious movie audiences all over the world, who see in his work a continuation of the great literary traditions of nineteenth-century Russia. Many critics have tried to interpret his intensely personal vision, but he himself always remained inaccessible.In Sculpting in Time, Tarkovsky sets down his thoughts and his memories, revealing for the first time the original inspirations for his extraordinary films--Ivan''s Childhood, Andrey Rublyov, Solaris, The Mirror, Stalker, Nostalgia, and The Sacrifice. He discusses their history and his methods of work, he explores the many problems of visual creativity, and he sets forth the deeply autobiographical content of part of his oeuvre--most fascinatingly in The Mirror and Nostalgia. The closing chapter on The Sacrifice, dictated in the last weeks of Tarkovsky''s life, makes the book essential reading for those who already know or who are just discovering his magnificent work.', DATE '2026-03-26', DATE '2026-04-26');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (89, '9781170000000', 'The Beggars Opera', 15, 'Gale Ecco, Print Editions', 2010, 10.1, 33, 's/t: as It Is Acted at Both the Theatres Royal, in Drury-Lane, and Covent-Garden. Written by Mr. Gay. Dramatis Person... This data is provided as an additional tool in helping to insure edition identification: ++++Harvard University Houghton LibraryN014800Text is printed in two columns. Horizontal chain lines.London: printed in the year, 1760. 27, 1]p.; 8', DATE '2026-03-29', DATE '2026-05-06');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (90, '9780400000000', 'The Complete Poems', 15, 'Mariner Books', 1999, 4.55, 28, 'From the joy and anguish of her own experience, Sexton fashioned poems that told truths about the inner lives of men and women. This book comprises Sexton''s ten volumes of verse, including the Pulitzer Prize-winner Live or Die, as well as seven poems from her last years.', DATE '2026-01-01', DATE '2026-02-15');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (91, '9780310000000', 'Dangerous Minds', 16, 'St. Martin''s Paperbacks', 1995, 4, 50, 'She bullied, bluffed, and bribed her students into caring about school.And if that didn''t work, the pretty, petite ex-marine told them she''d been trained to kill with her bare hands.They were called the class from Hell-thirty-four inner city sophomores she inherited from a teacher who''d been "pushed over the edge." She was told "those kids have tasted blood. They''re dangerous."But LouAnne Johnson had a different idea. Where the school system saw thirty-four unreachable kids, she saw young men and women with intelligence and dreams. When others gave up on them, she broke the rules to give them the best things a teacher can give-hope and belief in themselves. When statistics showed the chances were they''d never graduate, she fought to beat the odds.This is her remarkable story-and theirs. If you loved Stand and Deliver, you''ll stand up and cheer for LouAnne Johnson and Dangerous Minds.', DATE '2026-01-04', DATE '2026-02-25');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (92, '9781600000000', 'Holy Bible: The Greek New Testament', 16, 'Hendrickso', 2006, 51.03, 22, 'While the Nestle-Aland Novum Testamentum Graece is designed for scholarly research, the Greek New Testament, 4th Revised Edition is designed for translators and students. Like NA27, this is the leading edition of the original text of the New Testament. It contains the same Greek text as NA27, differing only in some details of punctuation and paragraphing. The format of UBS4 is in several respects more user-friendly for students and translators than NA27. It has a more spacious appearance and a larger font. English sub-headings assist in navigating the text for those who may be less familiar with Greek. Old Testament quotations appear in easily recognizable bold font. Synoptic parallels are clearly listed under English headings. The critical apparatus includes exegetically significant variants (fewer than NA27) but adds extensive manuscript evidence (more than NA27) for each variant, thereby offering in-depth instruction for students on how variants and the evidence for them work together. An introduction in English is included.', DATE '2026-01-07', DATE '2026-03-07');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (93, '9781560000000', 'Mayo Clinic Guide to Your Baby''s First Year: From Doctors Who Are Parents, Too!', 16, 'Da Capo Lifelong Books', 2012, 3.29, 47, 'A steady,ever-present resource of both information and wisdom for brand-new parents taking care of their child from the newborn stage through the baby''s first year of life. When you''re faced with a perplexing development, reach for this complete Guide by the baby experts at the renowned Mayo Clinic By doctors who are also parents.Yikes, you''re suddenly parents, home alone with your brand-new baby! Where''s your own mother or smart friend;where''s your pediatrician; when you desperately need reassurance and advice? Mayo Clinic Guide to Your Baby''s First Year is a steady, ever-present source of both information and wisdom. When you''re faced with a perplexing development, reach for this complete Guide by the baby experts at the renowned Mayo Clinic. When you wonder what might happen next, check the "Month-by-Month Growth and Development" pages of this trusted companion.', DATE '2026-01-10', DATE '2026-01-11');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (94, '9780800000000', 'The 36-Hour Day: A Family Guide to Caring for People with Alzheimer Disease, Other Dementias, and Memory Loss in Later Life', 16, 'The Johns Hopkins University Press', 2006, 3.8, 14, 'Revised in 2006 for its twenty-fifth anniversary, this best-selling book is the "bible" for families caring for people with Alzheimer disease, offering comfort and support to millions worldwide. In addition to the practical and compassionate guidance that have made The 36-Hour Day invaluable to caregivers, the fourth edition is the only edition currently available that includes new information on medical research and the delivery of care.The new edition includes:-new information on diagnostic evaluation-resources for families and adult children who care for people with dementia-updated legal and financial information-the latest information on nursing homes and other communal living arrangements-new information on research, medications, and the biological causes and effects of dementiaAlso available in a large print editionPraise for The 36-Hour Day:', DATE '2026-01-13', DATE '2026-01-21');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (95, '9780770000000', 'Under the Tuscan Sun', 16, 'Broadway Books', 1997, 1.45, 27, 'An enchanting and lyrical look at the life, the traditions, and the cuisine of Tuscany, in the spirit of Peter Mayle''s A Year in Provence. Frances Mayes entered a wondrous new world when she began restoring an abandoned villa in the spectacular Tuscan countryside. There were unexpected treasures at every turn: faded frescos beneath the whitewash in her dining room, a vineyard under wildly overgrown brambles in the garden, and, in the nearby hill towns, vibrant markets and delightful people. In Under the Tuscan Sun, she brings the lyrical voice of a poet, the eye of a seasoned traveler, and the discerning palate of a cook and food writer to invite readers to explore the pleasures of Italian life and to feast at her table.', DATE '2026-01-16', DATE '2026-01-31');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (96, '9780140000000', 'A Room of One''s Own', 17, 'Penguin Books', 2000, 1.85, 42, 'A Room of One''s Own is an extended essay by Virginia Woolf. First published on the 24th of October, 1929, the essay was based on a series of lectures she delivered at Newnham College and Girton College, two women''s colleges at Cambridge University in October 1928. While this extended essay in fact employs a fictional narrator and narrative to explore women both as writers and characters in fiction, the manuscript for the delivery of the series of lectures, titled Women and Fiction, and hence the essay, are considered nonfiction. The essay is seen as a feminist text, and is noted in its argument for both a literal and figural space for women writers within a literary tradition dominated by patriarchy.', DATE '2026-01-19', DATE '2026-02-10');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (97, '9780630000000', 'The Civilizing Process', 17, 'Wiley-Blackwell', 2000, 32.12, 12, 'The Civilizing Process stands out as Norbert Elias'' greatest work, tracing the "civilizing" of manners and personality in Western Europe since the late Middle Ages by demonstrating how the formation of states and the monopolization of power within them changed Western society forever.', DATE '2026-01-22', DATE '2026-02-20');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (98, '9780160000000', 'The Common Reader', 17, 'Mariner Books', 2002, 5.76, 33, 'Woolf''s first and most popular volume of essays. This collection has more than twenty-five selections, including such important statements as "Modern Fiction" and "The Modern Essay."', DATE '2026-01-25', DATE '2026-03-02');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (99, '9780810000000', 'This I Believe: The Personal Philosophies of Remarkable Men and Women', 17, 'Henry Holt & Company', 2006, 5.2, 36, 'An inspiring collection of the personal philosophies of a group of remarkable men and women" "Based on the National Public Radio series of the same name, "This I Believe" features eighty essayists--from the famous to the unknown--completing the thought that begins the book''s title. Each piece compels readers to rethink not only how they have arrived at their own personal beliefs but also the extent to which they share them with others. Featuring a well-known list of contributors--including Isabel Allende, Colin Powell, Gloria Steinem, William F. Buckley Jr., Penn Jillette, Bill Gates, and John Updike--the collection also contains essays by a Brooklyn lawyer; a part-time hospital clerk from Rehoboth, Massachusetts; a woman who sells Yellow Pages advertising in Fort Worth, Texas; and a man who serves on the state of Rhode Island''s parole board. The result is a stirring and provocative trip inside the minds and hearts of a diverse group of people whose beliefs--and the incredibly varied ways in which they choose to express them--reveal the American spirit at its best.', DATE '2026-01-28', DATE '2026-03-12');
INSERT INTO BOOKS (BOOK_ID, ISBN, TITLE, CATEGORY_ID, PUBLISHER, PUBLISH_YEAR, PRICE, STOCK_QTY, DESCRIPTION, CREATED_AT, UPDATED_AT) VALUES (100, '9781440000000', 'Todo in Tuscany: The Dog at the Villa', 17, 'Hodder & Stoughton', 2012, 3.54, 37, 'A dream house in Tuscany . . . and a dog named Todo.Todo had been waiting at Poggiolino since his mistress died over two years before. The house lay empty and neglected and yet he wouldn''t leave. He seemed to know that someday the right people would come along and make it a home again.Louise and Lawrence weren''t thinking of buying the very first house they looked at in Tuscany. In fact, their plans to move from London were barely formed . . . but there was something enchanting about the dog waiting at the gates. If they were honest, they wanted Todo - the scruffy dog with the huge grin - as much as they wanted the house.With Todo as their faithful companion they began to restore Poggiolino to life, unlocking her secrets and giving Todo, their beloved dog, a second chance.A heart-warming memoir of moving country, making a new life and coming home.', DATE '2026-01-31', DATE '2026-03-22');
